descriptor.templateCss:
.alarm-card-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #64B856;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  transition: all 0.3s ease;
}
.alarm-card-container.alert {
  border-top-color: #ef4444;
  background: linear-gradient(180deg, rgba(239, 68, 68, 0.06) 0%, #151d2a 100%);
}
.alarm-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.alarm-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.alarm-icon { font-size: 16px; }
.alarm-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
  white-space: nowrap;
}
.alarm-badge.healthy {
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.08);
}
.alarm-badge.alert {
  color: #ef4444;
  border: 1.5px solid #ef4444;
  background: rgba(239, 68, 68, 0.15);
  animation: pulse 1.5s infinite;
}
@keyframes pulse {
  0% { opacity: 1; }
  50% { opacity: 0.5; }
  100% { opacity: 1; }
}
.alarm-tiles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin: 6px 0;
}
.alarm-tile {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.15);
  border-radius: 10px;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.tile-kpi-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #94a3b8;
}
.tile-kpi-num {
  font-size: 28px;
  font-weight: 800;
  line-height: 1.1;
}
.tile-kpi-num.healthy { color: #64B856; }
.tile-kpi-num.alert { color: #ef4444; }
.tile-kpi-num.normal { color: #cbd5e1; }
.tile-kpi-num.warn { color: #f59e0b; }
.tile-kpi-status {
  font-size: 10px;
  color: #64748b;
}
.alarm-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 8px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var activas = 0;
  var fallas30d = 1;
  var warns30d = 4;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseInt(item.data[item.data.length - 1][1], 10);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('activas') !== -1 || i === 0) activas = v;
          else if (k.indexOf('faults') !== -1 || i === 1) fallas30d = v;
          else if (k.indexOf('warnings') !== -1 || i === 2) warns30d = v;
        }
      }
    }
  }

  var hasAlert = activas > 0;
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var card = container.querySelector('#alarm-card');
    if (card) card.className = 'alarm-card-container ' + (hasAlert ? 'alert' : 'healthy');

    var elBadge = container.querySelector('#alarm-status-badge');
    if (elBadge) {
      elBadge.textContent = hasAlert ? 'ALARMA ACTIVA (' + activas + ')' : 'SISTEMA SALUDABLE';
      elBadge.className = 'alarm-badge ' + (hasAlert ? 'alert' : 'healthy');
    }

    var elAct = container.querySelector('#val-active-alarms');
    if (elAct) {
      elAct.textContent = activas;
      elAct.className = 'tile-kpi-num ' + (hasAlert ? 'alert' : 'healthy');
    }

    var elF = container.querySelector('#val-faults-30d');
    if (elF) elF.textContent = fallas30d;

    var elW = container.querySelector('#val-warnings-30d');
    if (elW) elW.textContent = warns30d;
  }
};
self.onDestroy = function() {};
